<script setup lang="ts">
import { onMounted, onUnmounted, ref, watch } from 'vue';
import { gsap } from 'gsap';
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { useRouterTransition } from '../../composables/useRouterTransition';

gsap.registerPlugin(ScrollTrigger);

const props = defineProps({
  skipAnimation: Boolean
})

const emit = defineEmits<{
  (e: 'tlComplete'): void
}>()

const { isTransitionComplete } = useRouterTransition();

const root = ref();
const content = ref();
const tiffany = ref();
const tLine = ref();
const iDot = ref();
const choong = ref();
const pattern = ref();

const tiffStrokeLength = ref(0);
const lineStrokeLength = ref(0);

let ctx: gsap.Context;
let tl = gsap.timeline({ delay: 0.5, paused: true });

onMounted(() => {
	tiffStrokeLength.value = Math.round(tiffany.value?.getTotalLength());
	lineStrokeLength.value = Math.round(tLine.value?.getTotalLength());

  tl
    .from(content.value, {
      duration: 0.5,
      opacity: 0
    })
    .from(tiffany.value, {
      duration: 1.5,
      ease: 'power2.inOut',
      'stroke-dashoffset': tiffStrokeLength.value
    })
    .from(tLine.value, {
      duration: 0.5,
      ease: 'power2.in',
      'stroke-dashoffset': lineStrokeLength.value
    })
    .from(iDot.value, {
      duration: 0.5,
      ease: 'elastic.out(1, 0.4)',
      scale: 0
    })
    .from(choong.value, {
      duration: 1,
      ease: 'elastic.out(1, 0.4)',
      opacity: 0,
      scale: 0.8
    });
});

watch(
  [() => isTransitionComplete.value, root],
  ([newIsTransitionComplete]) => {
    if (newIsTransitionComplete && root.value) {
      ctx = gsap.context(() => {
        let observer = new IntersectionObserver(entries => {    
          if (entries[0].isIntersecting && !props.skipAnimation) {
            tl
              .play()
              .then(() => {
                emit('tlComplete');
              });

          } else {
            tl.progress(1);
            gsap
              .from(content.value, {
                duration: 0.5,
                opacity: 0
              });
            emit('tlComplete');
          }

          observer.unobserve(root.value);
        });
        observer.observe(root.value);
    
        gsap.to(content.value, {
          yPercent: 100,
          ease: 'none',
          scrollTrigger: {
            trigger: root.value,
            start: 'top top',
            end: 'bottom top',
            scrub: true
          }, 
        });

        gsap.to(pattern.value, {
          yPercent: 50,
          ease: 'none',
          scrollTrigger: {
            trigger: root.value,
            start: 'top top',
            end: 'bottom top',
            scrub: true
          }, 
        });
      }, root.value);
    }
  },
  {
    immediate: true,
  }
);

onUnmounted(() => {
  ctx?.revert();
});

defineExpose({
  root
})
</script>

